// stage content:
(lib.final_holterman = function(mode,startPosition,loop,reversed) {
if (loop == null) { loop = true; }
if (reversed == null) { reversed = false; }
	var props = new Object();
	props.mode = mode;
	props.startPosition = startPosition;
	props.labels = {};
	props.loop = loop;
	props.reversed = reversed;
	cjs.MovieClip.apply(this,[props]);

	this.actionFrames = [0,1];
	// timeline functions:
	this.frame_0 = function() {
		this.stop();
		
		var root = this;
		var speed = 5;
		
		this.play_btn.addEventListener("click", handleClickPlayButton);
		
		function handleClickPlayButton(event) {
			var music_snd = createjs.Sound.play("music");
			root.play();
		}
		
		this.background_mc.cloud_mc.addEventListener("click", handleClickCloud);
		
		function handleClickCloud(event) {
			var bleh_snd = createjs.Sound.play("bleh");
			root.background_mc.cloud_mc.play();
		}
		
		this.background_mc.hole_mc.addEventListener("click", handleClickHole);
		
		function handleClickHole(event) {
			var laugh_snd = createjs.Sound.play("laugh");
			root.background_mc.hole_mc.play();
		}
		
		
		this.background_mc.woodpeacker_mc.addEventListener("click", handleClickWoodPeacker);
		
		function handleClickWoodPeacker(event) {
			var bird_snd = createjs.Sound.play("bird");
			root.background_mc.woodpeacker_mc.play();
		}
		
		
		
		
		// KEYBOARD INPUT
		this.stop();
		
		document.addEventListener("keydown", handleKeyDown);
		document.addEventListener("keyup", handleKeyUp);
		
		var root = this;
		var speed = 5;
		
		function handleKeyDown(event) {
			console.log(root.background_mc.x);
		
			if (root.snail_mc.currentFrame == 9) {
				root.snail_mc.gotoAndPlay("walking");
			}
		
			if (event.keyCode == 39 && root.background_mc.x > -1340) {
				root.snail_mc.scaleX = 0.2028;
				root.background_mc.x = root.background_mc.x - speed;
				console.log(root.background_mc.x);
			}
		
			if (event.keyCode == 37 && root.background_mc.x < 2294) {
				root.snail_mc.scaleX = -0.2028;
				root.background_mc.x = root.background_mc.x + speed;
			}
		}
		
		function handleKeyUp(event) {
			root.snail_mc.gotoAndPlay("standing");
		}
		
		
		//CLOUD CLICK
		root.background_mc.cloud_mc.addEventListener("click", sadFace);
		
		var root = this;
		
		function sadFace(event) {
			console.log("Cloud Will Get Sad");
			root.background_mc.cloud_mc.play();
		}
		
		//HOLE CLICK
		root.background_mc.hole_mc.addEventListener("click", scaryEyes);
		
		var root = this;
		
		function scaryEyes(event) {
			console.log("Hole Will Get Scary");
			root.background_mc.hole_mc.play();
		}
		
		//WOOD PEACKER CLICK
		root.background_mc.woodpeacker_mc.addEventListener("click", woodPeacks);
		
		var root = this;
		
		function woodPeacks(event) {
			console.log("Wood Peacker Will Peack");
			root.background_mc.woodpeacker_mc.play();
		}
	}
	this.frame_1 = function() {
		this.stop();
	}

	// actions tween:
	this.timeline.addTween(cjs.Tween.get(this).call(this.frame_0).wait(1).call(this.frame_1).wait(1));

	// text
	this.play_btn = new lib.playButton();
	this.play_btn.name = "play_btn";
	this.play_btn.setTransform(1115.15,398.55,0.4138,0.3661);
	new cjs.ButtonHelper(this.play_btn, 0, 1, 2, false, new lib.playButton(), 3);

	this.instance = new lib.CachedBmp_1();
	this.instance.setTransform(1017.05,124.55,0.5,0.5);

	this.timeline.addTween(cjs.Tween.get({}).to({state:[{t:this.instance},{t:this.play_btn}]}).to({state:[]},1).wait(1));

	// buttons
	this.instance_1 = new lib.ladybug();
	this.instance_1.setTransform(1203.3,766.4,0.4192,0.4362);
	new cjs.ButtonHelper(this.instance_1, 0, 1, 1);

	this.timeline.addTween(cjs.Tween.get(this.instance_1).to({_off:true},1).wait(1));

	// walking
	this.snail_mc = new lib.snail();
	this.snail_mc.name = "snail_mc";
	this.snail_mc.setTransform(888.7,786.55,0.2028,0.2861,0,0,0,489.9,162);
	this.snail_mc._off = true;

	this.timeline.addTween(cjs.Tween.get(this.snail_mc).wait(1).to({_off:false},0).wait(1));

	// background
	this.instance_2 = new lib.butterfly();
	this.instance_2.setTransform(503.05,579.9,1,1,0,0,0,472.7,-85.4);

	this.instance_3 = new lib.CachedBmp_2();
	this.instance_3.setTransform(-57.75,-19.5,0.5,0.5);

	this.background_mc = new lib.background_1();
	this.background_mc.name = "background_mc";
	this.background_mc.setTransform(1146.85,411.75,0.8704,0.4301,0,0,0,2443.8,-649.8);

	this.instance_4 = new lib.CachedBmp_4();
	this.instance_4.setTransform(351.4,659.3,0.5,0.5);

	this.instance_5 = new lib.CachedBmp_3();
	this.instance_5.setTransform(-249.05,437.15,0.5,0.5);

	this.timeline.addTween(cjs.Tween.get({}).to({state:[{t:this.instance_3},{t:this.instance_2}]}).to({state:[{t:this.instance_5},{t:this.instance_4},{t:this.background_mc}]},1).wait(1));

	this._renderFirstFrame();

}).prototype = p = new lib.AnMovieClip();
